package com.swp5.library_management.controller; import com.swp5.library_management.entity.User; import com.swp5.library_management.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RestController; import java.util.List; @RestController @RequiredArgsConstructor public class DebugController { private final UserRepository userRepository; @GetMapping("/debug/users") public List<User> getAllUsers() { return userRepository.findAll(); } }